import {newStyles,isEndcap} from './phase3-layout.js';
import {surfaces,shelves} from './plan.js';
const $=id=>document.getElementById(id);
const number=(id,label,step='.125')=>`<label>${label}<input id="${id}" type="number" step="${step}"></label>`;
const select=(id,label,options)=>`<label>${label}<select id="${id}">${options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`;
const check=(id,label)=>`<label class="check"><input type="checkbox" id="${id}">${label}</label>`;
const nums=['palletWidth','palletDepth','trayWidth','trayDepth','trayColumns','trayRows','moduleGap','flangeHeight','flangeExtent','rearHeight','fixtureDepth','fixtureHeight','removalClearance','guideBodyMax','guideTrayMax','guideEndcapMax'];
const sels=['faces','trayOrientation','trayFacing','endcapMode'];
export function installControls(){
 document.querySelector('.formats').insertAdjacentHTML('beforeend',Object.entries(newStyles).map(([id,name])=>`<button class="format" data-type="${id}"><span>${id.startsWith('end')?'▤':id==='stack'?'▦':'▱'}</span><b>${name}</b><small>${id==='full'?'2 or 4 shopping faces':id==='stack'?'Aligned locking modules':id==='flange'?'Rounded support wings':'Metal fixture / secured insert'}</small></button>`).join(''));
 document.querySelector('.referenceActions').insertAdjacentHTML('afterend',`<div id="phase3Controls"><div class="formatControls" id="palletOptions"><b>Actual pallet footprint</b><div class="fields">${number('palletWidth','Pallet width')}${number('palletDepth','Pallet depth')}</div><div id="fullOptions">${select('faces','Shopping faces',[[2,'Two opposing faces'],[4,'Four independent faces']])}</div><div id="stackOptions">${select('palletSize','Stacking pallet preset',[['full','Full · 48 × 40'],['half','Half · 48 × 20']])}<div class="fields">${number('trayWidth','Tray outer W')}${number('trayDepth','Tray outer D')}${number('trayColumns','Columns','1')}${number('trayRows','Rows per level','1')}${number('moduleGap','Module gap')}${select('trayOrientation','Tray orientation',[[0,'0°'],[90,'90°']])}</div>${select('trayFacing','Tray access',[['outward','Outward from each pallet side'],['front','All face front']])}</div></div><div id="flangeOptions" class="formatControls"><b>Flange construction</b><div class="fields">${number('flangeHeight','Flange height')}${number('flangeExtent','Wing width each side')}${number('rearHeight','Rear support height')}${check('retention','Retention tabs')}</div><p class="hint">Overall width includes both rounded flanges. Inner space excludes retention tabs.</p></div><div id="endcapOptions" class="formatControls"><b id="fixtureLabel"></b>${select('endcapMode','Construction',[['fixture','Steel fixture shelves'],['corrugated','Corrugated insert · secured to fixture']])}<div class="fields">${number('fixtureDepth','Physical fixture D')}${number('fixtureHeight','Physical fixture H')}</div><p class="hint">Width / depth / height below describe the active selling area or insert. Nominal fixture width stays separate.</p></div></div>`);
 $('compartments').closest('.fields').insertAdjacentHTML('afterend',`<label>Divider positions · % of clear width<input id="dividerPositions" placeholder="Equal by default · e.g. 35, 70"></label><div class="fields">${number('removalClearance','Product removal clearance')}</div>`);
 $('skuSelect').closest('.catalogPicker').insertAdjacentHTML('beforebegin','<label>Find SKU by code or name<input id="skuSearch" type="search" placeholder="Search this concept’s catalog"></label>');
 $('skuPrice').closest('label').insertAdjacentHTML('afterend',number('skuCost','Unit cost','.01'));
 $('guideNotes').insertAdjacentHTML('afterend',`<details><summary>Historical guide warning settings</summary>${check('guideWarnings','Show historical dimension warnings')}<div class="fields">${number('guideBodyMax','Pallet body limit')}${number('guideTrayMax','Tray depth limit')}${number('guideEndcapMax','Insert height limit')}</div><p class="hint">Changing reference limits does not change your geometry or certify compliance. Collision and support errors always remain active.</p></details>`);
 document.querySelector('.exportOptions').insertAdjacentHTML('afterbegin',select('environment','Preview environment',[['studio','White studio'],['store','Store context']])+select('exportEnvironment','PNG environment',[['studio','White studio'],['current','Current environment']]));
 document.querySelector('.allocationPanel>.hint').textContent='Assign a SKU to each face, shelf, module or compartment. Blank facings / depth use the available space; blank units fills it. Each format keeps its own allocations.';
 document.querySelector('.note p').textContent='Supplied 2017 Walmart Canada guide · pp.17–33, 77–78. Historical reference defaults. Current buyer requirements, physical loads, attachment and shopper access require review.';
}
export function syncControls(s){for(const id of nums)$(id).value=s[id]??({guideBodyMax:43,guideTrayMax:14,guideEndcapMax:70,removalClearance:0}[id]??'');for(const id of sels)$(id).value=s[id]??'';$('retention').checked=!!s.retention;$('guideWarnings').checked=s.guideWarnings!==false;$('dividerPositions').value=(s.dividerPositions||[]).join(', ');$('palletOptions').hidden=!['full','stack'].includes(s.type);$('fullOptions').hidden=s.type!=='full';$('stackOptions').hidden=s.type!=='stack';$('flangeOptions').hidden=s.type!=='flange';$('endcapOptions').hidden=!isEndcap(s.type);$('fixtureLabel').textContent=`${s.fixtureWidth} in nominal fixture · ${s.type==='end36'?35.5:47.5} in insert reference`;$('palletSize').value=s.palletDepth===20?'half':'full';for(const id of ['levels','base','header'])$(id).disabled=!shelves(s.type)&&s.type!=='waterfall';if(s.type==='stack')$('header').disabled=true;$('shelfClass').disabled=!['single','tray','flange'].includes(s.type);}
export function bindControls(config,refresh,sync,engine){for(const id of [...nums,...sels,'retention','guideWarnings'])$(id).onchange=()=>{const s=config();s[id]=['retention','guideWarnings'].includes(id)?$(id).checked:['trayFacing','endcapMode'].includes(id)?$(id).value:Number($(id).value);if(id==='faces'){s.shelfDepths=[];s.slots={};}refresh();};for(const id of [...nums,...sels])$(id).oninput=$(id).onchange;$('dividerPositions').onchange=()=>{config().dividerPositions=$('dividerPositions').value.trim()?$('dividerPositions').value.split(',').map(x=>Number(x.trim())):[];refresh();};$('palletSize').onchange=()=>{const s=config(),half=$('palletSize').value==='half';Object.assign(s,{width:48,depth:half?20:40,palletWidth:48,palletDepth:half?20:40,trayWidth:23.7,trayDepth:19.7,trayColumns:2,trayRows:half?1:2,trayOrientation:0,tierHeights:[],slots:{}});sync();refresh();};$('environment').onchange=()=>engine()?.setEnvironment($('environment').value);}
export function tierControls(s){const r=surfaces(s),n=r.stepped?(s.type==='tray'?s.risers+1:s.levels):(shelves(s.type)?s.levels:1),body=s.height-s.base-s.header;
 $('tierLayout').innerHTML=Array.from({length:Math.max(0,Math.min(12,n||0))},(_,i)=>`<div class="fields"><label>Level ${i+1} ${r.stepped?'rise':'pitch'} (in)<input type="number" data-tier="${i}" data-axis="height" value="${s.tierHeights[i]??(r.stepped?(i===0?0:body/n):body/n)}" step=".125" min="0"></label>${r.stepped?`<label>Usable step depth<input type="number" data-tier="${i}" data-axis="depth" value="${s.tierDepths[i]??(s.depth-2*s.board)/n}" step=".125"></label>`:['half','full','end36','end48'].includes(s.type)?`<label>${s.type==='full'?'Depth per face zone':'Shelf depth'}<input type="number" data-tier="${i}" data-axis="shelfDepth" placeholder="Default" value="${s.shelfDepths?.[i]??''}" step=".125"></label>`:'<span class="hint">Supported module / tray level</span>'}</div>`).join('');$('tierHelp').textContent=r.stepped?`Step depths must sum to ${(s.depth-2*s.board).toFixed(2)} in. Rises accumulate front to back.`:`Level pitches must sum to ${body.toFixed(2)} in. Blank shelf depth uses the available selling area. Removal clearance is deducted from merchandise height.`;
}
